// =====================================================================
// IDLE CASH + CAPITAL CHECK
//
// Mirrors config/levers.yml -> leak_detection.idle_cash and capital
// =====================================================================
const CONFIG = {
  bufferGbp:                 2000,   // keep this liquid, don't flag it
  minAnnualGainGbp:          50,     // below this, stay silent
  assumedBestEasyAccessPct:  4.50,   // fallback if the live check fails
  monthlyInvestmentGbp:      0,      // 0 = not set up yet
  missedTransferGraceDays:   3,
};

const balances = $('Load Balances').all().map(i => i.json);
const capital  = $('Check Investment Transfer').first().json;

const findings = [];
const bestRate = CONFIG.assumedBestEasyAccessPct;

// ---------------- idle cash sitting at a poor rate ----------------
let totalIdle = 0;
for (const acct of balances) {
  const balance = parseFloat(acct.balance_gbp || 0);
  const rate    = parseFloat(acct.interest_rate_pct || 0);

  // Only the money above your liquidity buffer is genuinely "idle".
  const idle = balance - CONFIG.bufferGbp;
  if (idle <= 0) continue;

  const rateGap = bestRate - rate;
  if (rateGap <= 0) continue;

  const annualGain = +(idle * (rateGap / 100)).toFixed(2);
  if (annualGain < CONFIG.minAnnualGainGbp) continue;

  totalIdle += idle;

  findings.push({
    // Bucket the value so small balance wobbles don't re-raise the same
    // finding every week. Only a material change creates a new key.
    dedupe_key: `idle_cash:${acct.account_id}:${Math.floor(annualGain / 50) * 50}`,
    source: 'idle_cash',
    title: `£${idle.toFixed(0)} is sitting at ${rate.toFixed(2)}% — worth £${annualGain.toFixed(0)}/yr to move`,
    detail: `Account "${acct.account_label}" holds £${balance.toFixed(2)}. `
          + `After keeping £${CONFIG.bufferGbp} liquid, £${idle.toFixed(2)} could earn `
          + `roughly ${bestRate}% instead of ${rate.toFixed(2)}%. `
          + `That is about £${annualGain.toFixed(2)} a year for one transfer and no risk. `
          + `Check current best-buy easy-access rates before moving.`,
    annual_value_gbp: annualGain,
    minutes_required: 20,
  });
}

// ---------------- did the investment standing order fire? ----------------
if (CONFIG.monthlyInvestmentGbp > 0) {
  const count = parseInt(capital.transfer_count || 0, 10);
  if (count === 0) {
    findings.push({
      dedupe_key: `missed_investment:${new Date().toISOString().slice(0, 7)}`,
      source: 'capital',
      title: `This month's £${CONFIG.monthlyInvestmentGbp} investment transfer has not appeared`,
      detail: `No payment to an investment platform found in the last 40 days. `
            + `Either the standing order failed, or it was cancelled. `
            + `This is the one part of the system that compounds — worth 5 minutes to fix.`,
      annual_value_gbp: CONFIG.monthlyInvestmentGbp * 12,
      minutes_required: 5,
    });
  }
}

// ---------------- ISA deadline: use it or lose it ----------------
// UK tax year ends 5 April. Unused allowance does not roll over.
const now = new Date();
const year = now.getMonth() >= 3 ? now.getFullYear() + 1 : now.getFullYear();
const isaDeadline = new Date(`${year}-04-05T00:00:00Z`);
const daysToDeadline = Math.ceil((isaDeadline - now) / 86400000);

if (daysToDeadline <= 60 && daysToDeadline > 0) {
  const urgency = daysToDeadline <= 14 ? 'FINAL WARNING' : 'Heads up';
  findings.push({
    dedupe_key: `isa_deadline:${year}:${daysToDeadline <= 14 ? 'final' : 'early'}`,
    source: 'claims',
    title: `${urgency}: ${daysToDeadline} days until the ISA allowance resets`,
    detail: `The tax year ends 5 April ${year}. Any unused ISA allowance disappears — `
          + `it does not carry over. If you have cash you won't need for a few years, `
          + `sheltering it now costs nothing and saves tax on the growth forever.`,
    annual_value_gbp: 100,
    minutes_required: 30,
    due_date: isaDeadline.toISOString().slice(0, 10),
  });
}

findings.sort((a, b) => b.annual_value_gbp - a.annual_value_gbp);
return [{ json: { findings, total_idle_gbp: +totalIdle.toFixed(2) } }];

const data = $input.first().json;

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
}

const statements = (data.findings || []).map(f =>
  `INSERT INTO money.actions
  (dedupe_key, source, title, detail, annual_value_gbp, minutes_required, due_date, status)
VALUES (${esc(f.dedupe_key)}, ${esc(f.source)}, ${esc(f.title)}, ${esc(f.detail)},
        ${f.annual_value_gbp}, ${f.minutes_required}, ${esc(f.due_date || null)}, 'open')
ON CONFLICT (dedupe_key) DO NOTHING;`
);

statements.push(`INSERT INTO money.sync_log (workflow, ok, rows_ingested, message)
VALUES ('03-idle-cash', true, ${(data.findings || []).length}, ${esc(`£${data.total_idle_gbp || 0} idle`)});`);

return [{ json: { sql: statements.join('\n') } }];
